<!-- This file is generated by AI. -->

<!--
  从训练切分产物导入角色。

  交互是**一个对话框 + 两个路径框**: 依次弹出两个系统目录选择框时, 用户点完第一个还要再点
  第二个, 中间没有任何反馈, 很容易以为已经结束。

  导入条数**不设上限**, 但**条数很多时会先停下来问一句**: 每段音频都要拷进角色库并逐个解码
  规范化, 一次导入几千条既慢又占空间, 而用户往往不知道自己选的那份清单有多大。数字由后端
  预览给出 (与真正导入是同一套解析), 因此不存在"提示与实际不符"。

  ⚠️ 不带 `<style>` 块 —— 类名 (`.input-row` / `.settings-field` / `.import-preview` …) 来自全局 `styles.css`。
-->

<script lang="ts">
  import { open as openDialog } from '@tauri-apps/plugin-dialog';

  import type { ListImportPreview } from '../commands/voice';
  import { voicePreviewImport } from '../commands/voice';
  import { voiceController } from '../voice/controller';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';

  /**
   * 超过这个条数就先确认一次。300 大致是"一个人配一部戏的常规语料量"的上界: 到这个量级导入已经
   * 要花上一两分钟、拷进角色库的音频也可能上百 MB, 值得让用户知道自己选了什么。
   */
  const CONFIRM_THRESHOLD = 300;

  /** 预览里最多逐个列出的角色数 (再多就只给总数) */
  const PREVIEW_NAMES = 12;

  let { onClose, onImported }: { onClose: () => void; onImported: (message: string) => void } = $props();

  let listPath = $state('');
  let audioDir = $state('');
  let busy = $state(false);
  /** 已取得的预览 (仅当条数超过阈值时才需要用户再看一眼) */
  let preview = $state<ListImportPreview | null>(null);
  /**
   * 报错**就地显示**。
   *
   * 交给外层的角色面板没有意义: 这是个模态对话框, 用户看不到身后那块面板, 于是
   * "导入失败"会表现为"点了没反应"。
   */
  let error = $state<string | null>(null);

  const ready = $derived(listPath.trim().length > 0 && audioDir.trim().length > 0 && !busy);

  async function pickList(): Promise<void> {
    const picked = await openDialog({
      multiple: false,
      title: '选择清单文件',
      filters: [{ name: '文本清单', extensions: ['list', 'txt'] }],
    });
    if (typeof picked === 'string') {
      listPath = picked;
      preview = null;
      error = null;
    }
  }

  async function pickAudioDir(): Promise<void> {
    const picked = await openDialog({ directory: true, multiple: false, title: '选择音频目录' });
    if (typeof picked === 'string') {
      audioDir = picked;
      preview = null;
      error = null;
    }
  }

  async function importNow(): Promise<void> {
    const report = await voiceController.importFromList(listPath.trim(), audioDir.trim());
    onImported(
      `已导入 ${report.imported} 条参考音频，涉及 ${report.characters.length} 个角色` +
        (report.autoTrimmed > 0 ? `，其中 ${report.autoTrimmed} 条过长已自动裁剪` : '') +
        (report.skipped > 0 ? `，跳过 ${report.skipped} 条（音频缺失或无法读取）` : '') +
        (report.paired > 0 ? `，已按名称自动配对 ${report.paired} 个角色的 GSOV 模型` : '')
    );
    onClose();
  }

  /** 第一次点"导入"先取预览; 条数多则停下来确认, 否则直接导入 */
  async function confirm(): Promise<void> {
    if (!ready) return;
    busy = true;
    error = null;
    try {
      if (!preview) {
        const result = await voicePreviewImport(listPath.trim(), audioDir.trim());
        if (result.matched > CONFIRM_THRESHOLD) {
          preview = result;
          return;
        }
      }
      await importNow();
    } catch (caught) {
      error = caught instanceof Error ? caught.message : String(caught);
    } finally {
      busy = false;
    }
  }
</script>

<AppDialog
  title="从清单导入角色"
  description="选择训练切分产物里的清单文件与音频目录。匹配按**文件名**进行，因此两者放在哪里都可以。"
  size="medium"
  height={preview ? 440 : 360}
  {onClose}
>
  <div class="settings-field">
    <span class="settings-label">清单文件（.list）</span>
    <div class="input-row">
      <input
        class="ui-input"
        readonly
        value={listPath}
        placeholder="选择包含 路径|说话者|语言|文本 的 .list 文件"
        title={listPath}
      />
      <Button icon="Folder" title="选择清单文件" disabled={busy} onclick={() => void pickList()} />
    </div>
  </div>

  <div class="settings-field">
    <span class="settings-label">音频目录</span>
    <div class="input-row">
      <input
        class="ui-input"
        readonly
        value={audioDir}
        placeholder="选择存放切分音频的目录（可嵌套子目录）"
        title={audioDir}
      />
      <Button icon="Folder" title="选择音频目录" disabled={busy} onclick={() => void pickAudioDir()} />
    </div>
  </div>

  {#if preview}
    <div class="import-preview">
      <p class="voice-dialog-hint">
        将导入 <b>{preview.matched}</b> 条参考音频，涉及 {preview.characters.length} 个角色{preview.records >
        preview.matched
          ? `（清单里另有 ${preview.records - preview.matched} 条在音频目录中找不到，会跳过）`
          : ''}。
      </p>
      <ul class="import-preview-list">
        {#each preview.characters.slice(0, PREVIEW_NAMES) as item (item.name)}
          <li>{item.name} · {item.count} 条</li>
        {/each}
        {#if preview.characters.length > PREVIEW_NAMES}
          <li>…等 {preview.characters.length} 个角色</li>
        {/if}
      </ul>
      <p class="voice-dialog-hint">
        数量较多：每段音频都会被拷进角色库并逐个规范化，可能要花上几分钟并占用相应磁盘空间。
      </p>
    </div>
  {:else}
    <p class="voice-dialog-hint">过短的音频会在尾部补静音，过长的会按静音边界裁剪；导入条数不受限制。</p>
  {/if}

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}

  {#snippet footer()}
    {#if preview}
      <Button disabled={busy} onclick={() => (preview = null)}>返回</Button>
      <Button appearance="primary" disabled={busy} onclick={() => void confirm()}>
        {busy ? '导入中…' : `继续导入（${preview.matched} 条）`}
      </Button>
    {:else}
      <Button disabled={busy} onclick={onClose}>取消</Button>
      <Button appearance="primary" disabled={!ready} onclick={() => void confirm()}>
        {busy ? '处理中…' : '导入'}
      </Button>
    {/if}
  {/snippet}
</AppDialog>
